mapper.select:
SELECT id, biz_id, user_id_low, user_id_high, matched_at, source, created_at, updated_at, deleted FROM match_center."match" WHERE deleted = 0 AND (user_id_low = #{userId} OR user_id_high = #{userId})
AND (matched_at < #{cursorMatchedAt} OR (matched_at = #{cursorMatchedAt} AND biz_id < #{cursorBizId}))
ORDER BY matched_at DESC, biz_id DESC LIMIT #{pageSize}
